        INSERT OR IGNORE INTO products VALUES (1, 'Widget A', 'WA-001', 29.99, 'US-EAST', 150);
        INSERT OR IGNORE INTO products VALUES (2, 'Widget B', 'WB-002', 49.99, 'US-WEST', 75);
        INSERT OR IGNORE INTO products VALUES (3, 'Gadget C', 'GC-003', 99.99, 'EU-CENTRAL', 200);
