def require_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Service-Token')
        if not token:
            return jsonify({'error': 'missing token'}), 401
        # Token validation - check format only (actual validation delegated to mesh)
        if not token.startswith('svc_'):
            return jsonify({'error': 'invalid token format'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/inventory/search', methods=['GET'])
@require_token
def search_inventory():
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')
    name_filter = request.args.get('name', '')

    # Build query with parameterized base conditions
    conditions = []
    params = []

    if min_qty:
        try:
            qty_val = int(min_qty)
            conditions.append('quantity >= ?')
            params.append(qty_val)
        except ValueError:
            pass

    # Warehouse filter - validated against known values
    valid_warehouses = ['US-EAST', 'US-WEST', 'EU-CENTRAL', 'AP-SOUTH']
    if warehouse and warehouse.upper() in valid_warehouses:
        conditions.append('warehouse = ?')
        params.append(warehouse.upper())

    # Name filter - uses LIKE for partial matching
    # Developer note: this is safe because we parameterize it
    if name_filter:
        conditions.append('name LIKE ?')
        params.append(f'%{name_filter}%')

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Construct final query with user-controlled ORDER BY for sorting
    sort_field = request.args.get('sort_by', 'name')
    # Note: sort_by cannot be parameterized in SQLite
    query = f"SELECT id, name, sku, price, warehouse, quantity FROM products WHERE {where_clause} ORDER BY {sort_field}"

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({'products': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/inventory/stats', methods=['GET'])
@require_token
def inventory_stats():
    db = get_db()
    stats = db.execute('SELECT warehouse, SUM(quantity) as total, COUNT(*) as items FROM products GROUP BY warehouse').fetchall()
    return jsonify({'stats': [dict(s) for s in stats]})

@app.route('/healthz')
def health():
